const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Beijing geometry and time periods
  const beijing = ee.Geometry.Point([116.4074, 39.9042]).buffer(50000); // 50km radius around Beijing

  const period1Start = '2020-01-01';
  const period1End = '2020-01-20';
  const period2Start = '2020-02-10';
  const period2End = '2020-02-25';

  // 2. Load Sentinel-5P NO2 data
  const collection = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .select('tropospheric_NO2_column_number_density');

  const col1 = collection.filterDate(period1Start, period1End).filterBounds(beijing);
  const col2 = collection.filterDate(period2Start, period2End).filterBounds(beijing);

  const size1 = col1.size().getInfo();
  const size2 = col2.size().getInfo();

  console.log(`Period 1 (Jan 1-20): ${size1} images`);
  console.log(`Period 2 (Feb 10-25): ${size2} images`);

  // Check for empty collections
  if (size1 === 0 || size2 === 0) {
    console.log('Empty collection for one or both periods.');
    console.log('<answer>C1</answer>');
    return;
  }

  // 3. Apply QA filtering and create mean composites
  function maskPoorQuality(image) {
    const qa = image.select('qa_value');
    const mask = qa.gte(0.75);
    return image.updateMask(mask);
  }

  const s5pCol = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2');
  const col1WithQA = s5pCol.filterDate(period1Start, period1End).filterBounds(beijing).map(maskPoorQuality);
  const col2WithQA = s5pCol.filterDate(period2Start, period2End).filterBounds(beijing).map(maskPoorQuality);

  const mean1 = col1WithQA.select('tropospheric_NO2_column_number_density').mean();
  const mean2 = col2WithQA.select('tropospheric_NO2_column_number_density').mean();

  // 4. Calculate statistics with pixel counts
  const stats1 = mean1.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: beijing,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const stats2 = mean2.reduceRegion({
    reducer: ee.Reducer.mean().combine({reducer2: ee.Reducer.count(), sharedInputs: true}),
    geometry: beijing,
    scale: 5000,
    maxPixels: 1e9
  }).getInfo();

  const val1 = stats1['tropospheric_NO2_column_number_density_mean'];
  const count1 = stats1['tropospheric_NO2_column_number_density_count'];
  const val2 = stats2['tropospheric_NO2_column_number_density_mean'];
  const count2 = stats2['tropospheric_NO2_column_number_density_count'];

  console.log(`Jan mean NO2: ${val1}, Valid pixels: ${count1}`);
  console.log(`Feb mean NO2: ${val2}, Valid pixels: ${count2}`);

  // 5. Validate and determine answer
  if (count1 === 0 || count2 === 0) {
    console.log('No valid pixels after QA filtering.');
    console.log('<answer>C2</answer>');
    return;
  }

  if (val1 === null || val2 === null || isNaN(val1) || isNaN(val2)) {
    console.log('Calculation returned invalid values.');
    console.log('<answer>C3</answer>');
    return;
  }

  // Check if levels decreased (Feb < Jan)
  if (val2 < val1) {
    console.log(`NO2 decreased: ${val1.toExponential(3)} → ${val2.toExponential(3)}`);
    console.log('<answer>A</answer>');
  } else {
    console.log(`NO2 did not decrease: ${val1.toExponential(3)} → ${val2.toExponential(3)}`);
    console.log('<answer>B</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
